<script>
  // components/AddBookModal.tsx
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    let numericPrice: number | undefined = undefined;
    if (estimatedPrice) {
      numericPrice = parseFloat(estimatedPrice);
      if (isNaN(numericPrice)) {
        alert("Please enter a valid number for the estimated price.");
        return; // Prevent form submission
      }
    }

    if (isEditMode) {
      const updatedBook: Book = {
        ...bookToEdit,
        estimatedPrice: numericPrice,
      };
      onUpdateBook(updatedBook);
    } else {
      onAddBook({
        ...newBook,
        estimatedPrice: numericPrice,
      });
    }

    onClose();
  };
</script>
```


