import React from 'react';
import { BookOpenIcon } from './Icons';

interface HeaderProps {
  view: 'dashboard' | 'list' | 'wishlist';
  setView: (view: 'dashboard' | 'list' | 'wishlist') => void;
}

export const Header: React.FC<HeaderProps> = ({ view, setView }) => {
  const navItemClasses = "px-5 py-2 rounded-full text-sm font-semibold transition-all duration-200";
  const activeClasses = "bg-primary text-white shadow-md shadow-primary/20";
  const inactiveClasses = "text-text-secondary hover:bg-slate-100 hover:text-primary";

  return (
    <header className="bg-white border-b border-border-light sticky top-0 z-30 px-6 py-4">
      <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('dashboard')}>
            <div className="bg-primary p-2 rounded-xl shadow-lg shadow-primary/20">
                <BookOpenIcon className="h-6 w-6 text-white" />
            </div>
            <h1 className="text-xl font-bold font-serif text-slate-900 tracking-tight">Biblio<span className="text-primary">Tech</span></h1>
        </div>
        <nav className="flex items-center bg-slate-50 p-1 rounded-full border border-border-light">
            <button 
                onClick={() => setView('dashboard')}
                className={`${navItemClasses} ${view === 'dashboard' ? activeClasses : inactiveClasses}`}
            >
                Dashboard
            </button>
            <button 
                onClick={() => setView('list')}
                className={`${navItemClasses} ${view === 'list' ? activeClasses : inactiveClasses}`}
            >
                Minha Estante
            </button>
            <button 
                onClick={() => setView('wishlist')}
                className={`${navItemClasses} ${view === 'wishlist' ? activeClasses : inactiveClasses}`}
