import React, { useState, useEffect } from 'react';
import type { Book } from '../types';
import { TagIcon } from './Icons';

interface CurrentlyReadingProps {
  book: Book;
  updateBook: (book: Book) => void;
}

export const CurrentlyReading: React.FC<CurrentlyReadingProps> = ({ book, updateBook }) => {
    const [currentPage, setCurrentPage] = useState(book.currentPage || 0);

    useEffect(() => {
        setCurrentPage(book.currentPage || 0);
    }, [book.currentPage]);

    const handleProgressChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = parseInt(e.target.value, 10);
        if (!isNaN(value) && value >= 0 && value <= book.pages) {
            setCurrentPage(value);
        } else if (e.target.value === '') {
            setCurrentPage(0);
        }
    };

    const handleUpdateClick = () => {
        updateBook({ ...book, currentPage });
    };

    const progressPercentage = book.pages > 0 ? (currentPage / book.pages) * 100 : 0;

  return (
    <div className="bg-white p-8 rounded-2xl shadow-soft border border-slate-100 h-full flex flex-col relative overflow-hidden">
      <div className="absolute top-0 right-0 p-4">
        <span className="bg-primary/10 text-primary text-[10px] font-bold uppercase tracking-widest px-3 py-1 rounded-full border border-primary/20">
          Lendo agora
        </span>
      </div>

      <div className="flex flex-col sm:flex-row gap-8">
        <div className="relative group">
            <img
              src={book.coverImageUrl}
              alt={`Capa do livro ${book.title}`}
              className="w-40 h-60 object-cover rounded-xl shadow-2xl transition-transform duration-500 group-hover:scale-105 mx-auto sm:mx-0"
            />
            <div className="absolute inset-0 rounded-xl shadow-inner pointer-events-none border border-black/5"></div>
        </div>

        <div className="flex-1 flex flex-col justify-center text-center sm:text-left">
          <h3 className="text-2xl font-bold text-slate-900 mb-1 leading-tight">{book.title}</h3>
          <p className="text-lg text-slate-500 font-medium mb-4">{book.author}</p>

          <div className="flex items-center justify-center sm:justify-start gap-2 text-xs font-semibold text-primary mb-6">
              <span className="bg-slate-100 px-3 py-1 rounded-md border border-slate-200 uppercase tracking-tighter">
                {book.genre}
              </span>
          </div>

          <div className="mb-2 flex justify-between items-end">
            <span className="text-sm font-bold text-slate-900">{progressPercentage.toFixed(0)}% concluído</span>
            <span className="text-xs font-medium text-slate-400">{currentPage} / {book.pages} pág.</span>
          </div>

          <div className="w-full bg-slate-100 rounded-full h-3 mb-8 overflow-hidden border border-slate-200">
            <div 
                className="bg-primary h-full rounded-full transition-all duration-700 ease-out shadow-[0_0_10px_rgba(37,99,235,0.3)]" 
                style={{ width: `${progressPercentage}%` }}
            ></div>
          </div>

          <div className="flex items-center gap-3">
            <input 
                type="number"
                value={currentPage}
                onChange={handleProgressChange}
                min="0"
                max={book.pages}
                className="w-24 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-slate-900 font-bold focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all outline-none"
                aria-label="Página atual"
            />
            <button
                onClick={handleUpdateClick}
                className="flex-1 px-6 py-2.5 text-sm font-bold rounded-xl bg-primary text-white hover:bg-blue-700 shadow-lg shadow-primary/20 transition-all active:scale-95"
            >
                Atualizar Progresso
            </button>
          </div>
        </div>
      </div>

       <div className="mt-8 pt-6 border-t border-slate-100">
          <p className="text-sm text-slate-500 italic leading-relaxed">
            <span className="text-primary font-bold not-italic mr-2">Resumo:</span>
            "{book.summary}"
          </p>
      </div>
    </div>
  );
};

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell } from 'recharts';
import type { MonthlyStat } from '../types';

interface MonthlyChartProps {
  data: MonthlyStat[];
}

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white p-4 border border-slate-100 rounded-xl shadow-xl">
        <p className="font-bold text-slate-900 mb-2">{label}</p>
        <div className="space-y-1">
            <p className="text-sm flex justify-between gap-4">
                <span className="text-slate-500">Livros:</span>
                <span className="font-bold text-primary">{payload[0].value}</span>
            </p>
            <p className="text-sm flex justify-between gap-4">
                <span className="text-slate-500">Páginas:</span>
                <span className="font-bold text-slate-400">{payload[1].value}</span>
            </p>
        </div>
      </div>
    );
  }
  return null;
};

export const MonthlyChart: React.FC<MonthlyChartProps> = ({ data }) => {
  const chartData = data.filter(d => d.booksRead > 0).map(d => ({
      name: d.month.substring(0, 3),
      Livros: d.booksRead,
      Páginas: d.pagesRead,
  }));

  return (
    <div style={{ width: '100%', height: 350 }}>
      <ResponsiveContainer>
        <BarChart
          data={chartData}
          margin={{ top: 20, right: 30, left: 0, bottom: 0 }}
          barGap={8}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
          <XAxis 
            dataKey="name" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 600 }}
            dy={10}
          />
          <YAxis 
            yAxisId="left" 
            orientation="left" 
            axisLine={false} 
            tickLine={false}
            tick={{ fill: '#2563eb', fontSize: 11, fontWeight: 700 }}
          />
          <YAxis 
            yAxisId="right" 
            orientation="right" 
            axisLine={false} 
            tickLine={false}
            tick={{ fill: '#94a3b8', fontSize: 11, fontWeight: 700 }}
          />
          <Tooltip content={<CustomTooltip />} cursor={{ fill: '#f8fafc', radius: 10 }} />
          <Legend 
            verticalAlign="top" 
            align="right" 
            iconType="circle"
            wrapperStyle={{ paddingBottom: '20px' }}
          />
          <Bar 
            yAxisId="left" 
            dataKey="Livros" 
            fill="#2563eb" 
            radius={[6, 6, 0, 0]} 
            barSize={12}
          />
          <Bar 
            yAxisId="right" 
            dataKey="Páginas" 
            fill="#cbd5e1" 
            radius={[6, 6, 0, 0]} 
            barSize={12}
          />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

import React from 'react';
import type { ReadingStats, Book, DateFilter } from '../types';
import { StatCard } from './StatCard';
import { CurrentlyReading } from './CurrentlyReading';
import { MonthlyChart } from './MonthlyChart';
import { TypePieChart } from './TypePieChart';
import { BookOpenIcon, ChartBarIcon, StarIcon, TagIcon, HeartIcon } from './Icons';

interface DashboardProps {
  stats: ReadingStats;
  currentlyReading: Book | null;
  updateBook: (book: Book) => void;
  dateFilter: DateFilter;
  setDateFilter: (filter: DateFilter) => void;
