  estimatedPrice?: number;
  buyLink?: string; // Novo campo para link de compra
  currentPage?: number;
  dateAdded: string; // ISO string format (YYYY-MM-DD)
}

export type NewBook = Omit<Book, 'id' | 'monthRead'>;


export interface MonthlyStat {
  month: string;
  booksRead: number;
  pagesRead: number;
  avgRating: number;
}

export interface YearlyStats {
  booksRead: number;
  pagesRead: number;
  avgRating: number;
}

export interface TypeStat {
  type: BookType;
  count: number;
  pages: number;
  avgRating: number;
}

export interface ReadingStats {
  tbrCount: number;
  wishlistCount: number;
  yearly: YearlyStats;
  monthly: MonthlyStat[];
  byType: TypeStat[];
}

