import React, { useState, useCallback } from 'react';
import type { NewBook, Book } from '../types';
import { BookStatus, BookType } from '../types';
// Fixed: Added BookOpenIcon to the import statement.
import { XMarkIcon, BookOpenIcon } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => void;
  onUpdateBook: (book: Book) => void;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ onClose, onAddBook, onUpdateBook, bookToEdit, defaultStatus }) => {
  const isEditMode = !!bookToEdit;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [author, setAuthor] = useState(bookToEdit?.author || '');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [genre, setGenre] = useState(bookToEdit?.genre || '');
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState(bookToEdit?.rating?.toString() || '');
  const [yearRead, setYearRead] = useState(bookToEdit?.yearRead?.toString() || '');
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [coverImageUrl, setCoverImageUrl] = useState<string | undefined>(bookToEdit?.coverImageUrl);
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toString() || '');
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [currentPage, setCurrentPage] = useState(bookToEdit?.currentPage?.toString() || '');
  const [dateAdded, setDateAdded] = useState(bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]);

  const labelClass = "block text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1.5 ml-1";
  const inputClass = "w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-slate-900 focus:ring-4 focus:ring-primary/10 focus:border-primary outline-none transition-all";

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !author || pages <= 0) {
        alert("Por favor, preencha Título, Autor e Páginas.");
        return;
    }
    const numericRating = rating ? parseInt(rating, 10) : undefined;
    const numericYearRead = yearRead ? parseInt(yearRead, 10) : undefined;
    const numericPrice = estimatedPrice ? parseFloat(estimatedPrice) : undefined;
    const numericCurrentPage = currentPage ? parseInt(currentPage, 10) : undefined;

    const bookData = { 
        title, 
        author, 
        pages, 
        genre, 
        type, 
        status, 
        summary, 
        rating: numericRating, 
        yearRead: numericYearRead, 
        coverImageUrl, 
        estimatedPrice: numericPrice, 
        buyLink,
        currentPage: numericCurrentPage,
        dateAdded 
    };

    if (isEditMode) {
        onUpdateBook({ ...bookToEdit, ...bookData });
    } else {
        onAddBook(bookData);
    }
  };

  const handleGenerateSummary = useCallback(async () => {
    if (!title || !author) return;
    setIsGeneratingSummary(true);
    const result = await generateBookSummary(title, author);
    setSummary(result);
    setIsGeneratingSummary(false);
  }, [title, author]);

  const handleGenerateCover = useCallback(async () => {
    if (!title || !genre) return;
    setIsGeneratingCover(true);
    const result = await generateBookCover(title, genre, type);
    setCoverImageUrl(result);
    setIsGeneratingCover(false);
  }, [title, genre, type]);

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
            <h2 className="text-xl font-bold font-serif text-slate-900">{isEditMode ? 'Editar Livro' : 'Novo Livro'}</h2>
            <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 text-slate-400 transition-colors">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6 overflow-y-auto">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                    <label className={labelClass}>Título</label>
                    <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} required className={inputClass} placeholder="Ex: Dom Casmurro" />
                </div>
                <div>
                    <label className={labelClass}>Autor</label>
                    <input type="text" value={author} onChange={(e) => setAuthor(e.target.value)} required className={inputClass} placeholder="Ex: Machado de Assis" />
                </div>
                <div className="grid grid-cols-2 gap-3">
                    <div>
                        <label className={labelClass}>Páginas</label>
                        <input type="number" value={pages} onChange={(e) => setPages(Number(e.target.value))} required className={inputClass} />
                    </div>
                    <div>
                        <label className={labelClass}>Gênero</label>
                        <input type="text" value={genre} onChange={(e) => setGenre(e.target.value)} className={inputClass} placeholder="Drama" />
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <label className={labelClass}>Tipo de Mídia</label>
                    <select value={type} onChange={(e) => setType(e.target.value as BookType)} className={inputClass}>
                        <option value={BookType.Book}>Livro Físico/E-book</option>
                        <option value={BookType.HQ}>Quadrinhos / HQ</option>
                    </select>
                </div>
                <div>
                    <label className={labelClass}>Status de Leitura</label>
                    <select value={status} onChange={(e) => setStatus(e.target.value as BookStatus)} className={inputClass}>
                        <option value={BookStatus.TBR}>Quero Ler</option>
                        <option value={BookStatus.Reading}>Lendo no Momento</option>
                        <option value={BookStatus.Read}>Já Lido</option>
                        <option value={BookStatus.Wishlist}>Desejado (Wishlist)</option>
                    </select>
                </div>
            </div>

            {/* Campos de Wishlist / Compra */}
            {(status === BookStatus.Wishlist || isEditMode) && (
              <div className="p-6 bg-slate-50 rounded-2xl border border-slate-200 grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="md:col-span-2">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Informações de Compra</h4>
                  </div>
                  <div>
                      <label className={labelClass}>Valor Estimado (R$)</label>
                      <input 
                        type="number" 
                        step="0.01" 
                        value={estimatedPrice} 
                        onChange={(e) => setEstimatedPrice(e.target.value)} 
                        className={inputClass} 
                        placeholder="0,00"
                      />
                  </div>
                  <div>
                      <label className={labelClass}>Data de Registro</label>
                      <input 
                        type="date" 
                        value={dateAdded} 
                        onChange={(e) => setDateAdded(e.target.value)} 
                        className={inputClass} 
                      />
                  </div>
                  <div className="md:col-span-2">
                      <label className={labelClass}>Link para Loja</label>
                      <input 
                        type="url" 
                        value={buyLink} 
                        onChange={(e) => setBuyLink(e.target.value)} 
                        className={inputClass} 
                        placeholder="https://amazon.com.br/exemplo"
                      />
                  </div>
              </div>
            )}

            <div className="p-6 bg-blue-50/50 rounded-2xl border border-blue-100 flex flex-col sm:flex-row items-center gap-6">
                <div className="relative group">
                    {coverImageUrl ? (
                        <img src={coverImageUrl} alt="Capa" className="w-24 h-36 object-cover rounded-xl shadow-xl transition-all group-hover:scale-105"/>
                    ) : (
                        <div className="w-24 h-36 bg-slate-200 rounded-xl flex items-center justify-center">
                            <BookOpenIcon className="h-8 w-8 text-slate-400" />
                        </div>
                    )}
                </div>
                <div className="flex-1 text-center sm:text-left">
                    <h4 className="text-sm font-bold text-slate-800 mb-1">Capa Personalizada</h4>
                    <p className="text-xs text-slate-500 mb-4">Gere uma arte exclusiva via IA baseada nos dados do livro.</p>
                    <button type="button" onClick={handleGenerateCover} disabled={isGeneratingCover} className="px-4 py-2 text-xs font-bold rounded-lg bg-white text-primary border border-blue-200 hover:bg-blue-600 hover:text-white transition-all shadow-sm active:scale-95 disabled:opacity-50">
                        {isGeneratingCover ? 'Criando arte...' : 'Gerar com IA'}
                    </button>
                </div>
            </div>

            <div>
                <label className={labelClass}>Resumo & Reflexões</label>
                <textarea value={summary} onChange={(e) => setSummary(e.target.value)} rows={3} className={inputClass} placeholder="Sobre o que é este livro?"></textarea>
                <button type="button" onClick={handleGenerateSummary} disabled={isGeneratingSummary} className="mt-2 text-[10px] font-bold text-primary uppercase tracking-widest hover:underline disabled:opacity-50">
                    {isGeneratingSummary ? 'Redigindo...' : '✦ Gerar resumo inteligente'}
                </button>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-slate-100">
                <button type="button" onClick={onClose} className="px-6 py-2.5 rounded-xl text-slate-500 font-bold hover:bg-slate-100 transition-all">Descartar</button>
                <button type="submit" className="px-8 py-2.5 rounded-xl bg-primary text-white font-bold hover:bg-blue-700 shadow-lg shadow-primary/20 transition-all active:scale-95">
                    {isEditMode ? 'Salvar Edição' : 'Adicionar à Estante'}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

