              : 'group-hover:scale-105'
          }`}
        />
        <div className="absolute inset-0 rounded-lg shadow-inner pointer-events-none border border-black/5"></div>
      </div>

      <div className="flex-1 text-center md:text-left overflow-hidden">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-2 mb-1">
            <h3 className="text-xl font-bold text-slate-900 leading-tight truncate">{book.title}</h3>
            <div className="flex items-center gap-2 justify-center md:justify-start">
                {daysReading > 0 && (
                    <span className="text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-1 rounded-md border border-amber-100">
                        {daysReading === 1 ? 'Lendo há 1 dia' : `Lendo há ${daysReading} dias`}
                    </span>
                )}
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-2 py-1 rounded-md border border-slate-100">
                    Adicionado em {formatDate(book.dateAdded)}
                </span>
            </div>
        </div>
        <p className="text-slate-500 font-medium mb-4">{book.author}</p>

        <div className="flex flex-wrap justify-center md:justify-start items-center gap-2 mb-4">
            <span className={`px-2.5 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider border ${getStatusBadgeStyles(book.status)}`}>
                {book.status}
            </span>
            <span className="px-2.5 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider border bg-indigo-50 text-indigo-600 border-indigo-100">
                {book.type}
            </span>
            <span className="px-2.5 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider border bg-slate-50 text-slate-500 border-slate-100">
                {book.pages} pág.
            </span>
        </div>

        {book.rating && book.status === BookStatus.Read && (
            <div className="flex justify-center md:justify-start items-center gap-3 mb-3">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Nota</span>
                <StarRating rating={book.rating} />
            </div>
        )}

        {book.summary && (
            <p className="text-sm text-slate-400 italic line-clamp-1 group-hover:line-clamp-none transition-all duration-300">
                "{book.summary}"
            </p>
        )}
      </div>

      <div className="flex md:flex-col gap-2 w-full md:w-auto mt-4 md:mt-0">
        <button
          onClick={() => onEdit(book)}
          className="flex-1 px-5 py-2 text-xs font-bold rounded-xl bg-slate-50 text-slate-600 hover:bg-primary hover:text-white border border-slate-200 hover:border-primary transition-all active:scale-95"
        >
          Editar
        </button>
        <button
          onClick={() => onDelete(book)}
          className="flex-1 px-5 py-2 text-xs font-bold rounded-xl bg-white text-red-500 hover:bg-red-50 border border-red-100 transition-all active:scale-95"
        >
          Excluir
        </button>
      </div>
    </article>
  );
};

import React, { useState, useEffect } from 'react';
import type { Book } from '../types';
import { TagIcon } from './Icons';

interface CurrentlyReadingProps {
  book: Book;
  updateBook: (book: Book) => void;
}

const calculateDaysReading = (startDate?: string) => {
    if (!startDate) return 0;
    const start = new Date(startDate);
    const today = new Date();
    today.setHours(0,0,0,0);
    start.setHours(0,0,0,0);
    const diffTime = today.getTime() - start.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    // Se a data for futura, retornamos 0 ou tratamos como "Não iniciado"
    return diffDays >= 0 ? diffDays : 0;
}

export const CurrentlyReading: React.FC<CurrentlyReadingProps> = ({ book, updateBook }) => {
    const [currentPage, setCurrentPage] = useState(book.currentPage || 0);
    const [dateStarted, setDateStarted] = useState(book.dateStarted || new Date().toISOString().split('T')[0]);
    const daysReading = calculateDaysReading(dateStarted);

    useEffect(() => {
        setCurrentPage(book.currentPage || 0);
        setDateStarted(book.dateStarted || new Date().toISOString().split('T')[0]);
    }, [book.id, book.currentPage, book.dateStarted]);

    const handleProgressChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = parseInt(e.target.value, 10);
        if (!isNaN(value) && value >= 0 && value <= book.pages) {
            setCurrentPage(value);
        } else if (e.target.value === '') {
            setCurrentPage(0);
        }
    };

    const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setDateStarted(e.target.value);
    };

    const handleUpdateClick = () => {
        updateBook({ ...book, currentPage, dateStarted });
    };

    const progressPercentage = book.pages > 0 ? (currentPage / book.pages) * 100 : 0;

  return (
    <div className="bg-white p-8 rounded-2xl shadow-soft border border-slate-100 h-full flex flex-col relative overflow-hidden">
      <div className="absolute top-0 right-0 p-4 flex gap-2">
        {daysReading > 0 && (
          <span className="bg-amber-50 text-amber-600 text-[10px] font-bold uppercase tracking-widest px-3 py-1 rounded-full border border-amber-100 flex items-center gap-1">
             <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3">
                <path fillRule="evenodd" d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm.75-13a.75.75 0 0 0-1.5 0v5c0 .414.336.75.75.75h4a.75.75 0 0 0 0-1.5h-3.25V5Z" clipRule="evenodd" />
             </svg>
             {daysReading === 1 ? '1 dia' : `${daysReading} dias`}
          </span>
        )}
        <span className="bg-primary/10 text-primary text-[10px] font-bold uppercase tracking-widest px-3 py-1 rounded-full border border-primary/20">
          Lendo agora
        </span>
      </div>

      <div className="flex flex-col sm:flex-row gap-8">
        <div className="relative group">
            <img
              src={book.coverImageUrl}
              alt={`Capa do livro ${book.title}`}
              className="w-40 h-60 object-cover rounded-xl shadow-2xl transition-transform duration-500 group-hover:scale-105 mx-auto sm:mx-0"
            />
            <div className="absolute inset-0 rounded-xl shadow-inner pointer-events-none border border-black/5"></div>
        </div>

        <div className="flex-1 flex flex-col justify-center text-center sm:text-left">
          <h3 className="text-2xl font-bold text-slate-900 mb-1 leading-tight">{book.title}</h3>
          <p className="text-lg text-slate-500 font-medium mb-4">{book.author}</p>

          <div className="flex items-center justify-center sm:justify-start gap-2 text-xs font-semibold text-primary mb-6">
              <span className="bg-slate-100 px-3 py-1 rounded-md border border-slate-200 uppercase tracking-tighter">
                {book.genre}
              </span>
          </div>

          <div className="mb-2 flex justify-between items-end">
            <span className="text-sm font-bold text-slate-900">{progressPercentage.toFixed(0)}% concluído</span>
            <span className="text-xs font-medium text-slate-400">{currentPage} / {book.pages} pág.</span>
          </div>

          <div className="w-full bg-slate-100 rounded-full h-3 mb-8 overflow-hidden border border-slate-200">
            <div 
                className="bg-primary h-full rounded-full transition-all duration-700 ease-out shadow-[0_0_10px_rgba(37,99,235,0.3)]" 
                style={{ width: `${progressPercentage}%` }}
            ></div>
          </div>

          <div className="flex flex-col gap-4">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1.5 ml-1">Página Atual</label>
                <input 
                    type="number"
                    value={currentPage}
                    onChange={handleProgressChange}
                    min="0"
                    max={book.pages}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-slate-900 font-bold focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all outline-none"
                    aria-label="Página atual"
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1.5 ml-1">Início da Leitura</label>
                <input 
                    type="date"
                    value={dateStarted}
                    onChange={handleDateChange}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-slate-900 font-semibold focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all outline-none text-xs"
                    aria-label="Data de início"
                />
              </div>
            </div>

            <button
                onClick={handleUpdateClick}
                className="w-full px-6 py-2.5 text-sm font-bold rounded-xl bg-primary text-white hover:bg-blue-700 shadow-lg shadow-primary/20 transition-all active:scale-95"
            >
                Atualizar Progresso e Data
            </button>
          </div>
        </div>
      </div>

       <div className="mt-8 pt-6 border-t border-slate-100">
          <p className="text-sm text-slate-500 italic leading-relaxed">
            <span className="text-primary font-bold not-italic mr-2">Resumo:</span>
            "{book.summary}"
          </p>
      </div>
    </div>
  );
};

