      {/* Header Badges */}
      <div className="flex justify-between items-center mb-8 relative z-10">
        <div className="flex gap-2">
            <span className="bg-primary text-white text-[10px] font-black uppercase tracking-[0.15em] px-4 py-1.5 rounded-full shadow-lg shadow-primary/20">
              Lendo agora
            </span>
            {daysReading > 0 && (
              <span className="bg-slate-100 text-slate-500 text-[10px] font-bold uppercase tracking-widest px-4 py-1.5 rounded-full border border-slate-200">
                 Jornada de {daysReading} {daysReading === 1 ? 'dia' : 'dias'}
              </span>
            )}
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-10 items-center lg:items-start relative z-10">
        {/* Cover with realistic shadow */}
        <div className="relative group/cover flex-shrink-0">
            <div className="absolute -inset-1 bg-gradient-to-tr from-primary/20 to-transparent rounded-2xl blur opacity-25 group-hover/cover:opacity-50 transition-opacity duration-500"></div>
            <img
              src={book.coverImageUrl}
              alt={`Capa do livro ${book.title}`}
              className="w-48 h-72 object-cover rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.2)] transition-all duration-700 group-hover/cover:scale-[1.02] group-hover/cover:-rotate-1 relative z-10"
            />
            <div className="absolute inset-0 rounded-2xl shadow-inner pointer-events-none border border-white/20 z-20"></div>
        </div>

        <div className="flex-1 w-full text-center lg:text-left">
          <div className="mb-6">
            <h3 className="text-3xl font-black text-slate-900 mb-2 leading-tight font-serif italic">{book.title}</h3>
            <p className="text-xl text-slate-400 font-medium">{book.author}</p>
          </div>

          <div className="flex flex-wrap justify-center lg:justify-start gap-3 mb-8">
              <span className="bg-slate-50 text-slate-500 px-4 py-1.5 rounded-xl border border-slate-100 text-[10px] font-black uppercase tracking-widest">
                {book.genre}
              </span>
              <span className="bg-blue-50 text-primary px-4 py-1.5 rounded-xl border border-blue-100 text-[10px] font-black uppercase tracking-widest">
                {book.pages} páginas totais
              </span>
          </div>

          {/* Progress Section Premium */}
          <div className="mb-10">
            <div className="flex justify-between items-end mb-3">
                <div className="flex items-baseline gap-2">
                    <span className="text-4xl font-black text-slate-900 tracking-tighter">{progressPercentage.toFixed(0)}%</span>
                    <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Completo</span>
                </div>
                <div className="text-right">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Faltam</p>
                    <p className="text-sm font-bold text-slate-700">{pagesRemaining} páginas</p>
                </div>
            </div>

            <div className="w-full bg-slate-100 rounded-2xl h-4 mb-4 overflow-hidden p-1 border border-slate-200/50">
              <div 
                  className="bg-gradient-to-r from-primary to-blue-400 h-full rounded-xl transition-all duration-1000 ease-out relative" 
                  style={{ width: `${progressPercentage}%` }}
              >
                  <div className="absolute inset-0 bg-white/20 blur-[1px]"></div>
              </div>
            </div>

            {/* Smart Stats Grid */}
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
