import React, { useState, useMemo } from 'react';
import { useBookData } from './hooks/useBookData';
import { Header } from './components/Header';
import { Dashboard } from './components/Dashboard';
import { AddBookModal } from './components/AddBookModal';
import { PlusIcon } from './components/Icons';
import type { Book, NewBook } from './types';
import { BookList } from './components/BookList';
import { ConfirmationModal } from './components/ConfirmationModal';
import { BookStatus } from './types';
import { Wishlist } from './components/Wishlist';

export default function App() {
  const { books, stats, currentlyReading, addBook, updateBook, deleteBook, dateFilter, setDateFilter } = useBookData();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [view, setView] = useState<'dashboard' | 'list' | 'wishlist'>('dashboard');
  const [editingBook, setEditingBook] = useState<Book | null>(null);
  const [deletingBook, setDeletingBook] = useState<Book | null>(null);
  const [defaultStatusForModal, setDefaultStatusForModal] = useState<BookStatus | undefined>();

  const handleAddBook = (newBook: NewBook) => {
    addBook(newBook);
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const handleUpdateBook = (updatedBook: Book) => {
    updateBook(updatedBook);
    setIsModalOpen(false);
    setEditingBook(null);
  };

  const handleMoveToShelf = (book: Book) => {
    updateBook({ ...book, status: BookStatus.TBR });
  };

  const handleConfirmDelete = () => {
    if (deletingBook) {
      deleteBook(deletingBook.id);
      setDeletingBook(null);
    }
  };

  const openAddModal = (defaultStatus?: BookStatus) => {
    setEditingBook(null);
    setDefaultStatusForModal(defaultStatus);
    setIsModalOpen(true);
  };

  const openEditModal = (book: Book) => {
    setEditingBook(book);
    setIsModalOpen(true);
  };

  const openDeleteModal = (book: Book) => {
    setDeletingBook(book);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingBook(null);
    setDefaultStatusForModal(undefined);
  };

  const shelfBooks = useMemo(() => books.filter(book => book.status !== BookStatus.Wishlist), [books]);
  const wishlistBooks = useMemo(() => books.filter(book => book.status === BookStatus.Wishlist), [books]);

  const [isFading, setIsFading] = useState(false);

  const handleSetView = (newView: 'dashboard' | 'list' | 'wishlist') => {
    if (view !== newView) {
      setIsFading(true);
      setTimeout(() => {
        setView(newView);
        setIsFading(false);
      }, 200); // Reduzido ligeiramente para maior responsividade
    }
  };


  const renderContent = () => {
    switch(view) {
      case 'dashboard':
        return <Dashboard 
                  stats={stats} 
                  currentlyReading={currentlyReading} 
                  updateBook={updateBook}
                  dateFilter={dateFilter}
                  setDateFilter={setDateFilter} 
                />;
      case 'list':
        return <BookList books={shelfBooks} onEdit={openEditModal} onDelete={openDeleteModal} />;
      case 'wishlist':
        return <Wishlist 
                  books={wishlistBooks} 
                  onEdit={openEditModal} 
                  onDelete={openDeleteModal} 
                  onMoveToShelf={handleMoveToShelf} 
                  onAddWishlistItem={() => openAddModal(BookStatus.Wishlist)}
                />;
      default:
        return null;
    }
  }

  return (
    <div className="min-h-screen bg-background text-text-main">
      <Header view={view} setView={handleSetView} />

      {/* Transição suave com Opacidade e Deslocamento Vertical */}
      <main className={`p-4 md:p-8 transition-all duration-300 ease-in-out transform ${
        isFading 
          ? 'opacity-0 -translate-y-2' 
          : 'opacity-100 translate-y-0'
      }`}>
        {renderContent()}
      </main>

      <button
        onClick={() => openAddModal()}
        className="fixed bottom-8 right-8 bg-primary text-background p-4 rounded-full shadow-lg hover:bg-blue-700 transition-all duration-300 focus:outline-none focus:ring-4 focus:ring-primary/20 active:scale-95 z-40"
        aria-label="Adicionar novo livro"
      >
        <PlusIcon className="h-8 w-8" />
      </button>

      {isModalOpen && (
        <AddBookModal
          onClose={closeModal}
          onAddBook={handleAddBook}
          onUpdateBook={handleUpdateBook}
          bookToEdit={editingBook}
          defaultStatus={defaultStatusForModal}
          existingBooks={books}
        />
      )}

      {deletingBook && (
        <ConfirmationModal
          isOpen={!!deletingBook}
          onClose={() => setDeletingBook(null)}
          onConfirm={handleConfirmDelete}
          title="Confirmar Exclusão"
          message={`Tem certeza que deseja excluir o livro "${deletingBook.title}"? Esta ação não pode ser desfeita.`}
        />
      )}
    </div>
  );
}

import React, { useState, useCallback, useMemo } from 'react';
import type { NewBook, Book } from '../types';
import { BookStatus, BookType } from '../types';
import { XMarkIcon, BookOpenIcon } from './Icons';
import { generateBookSummary, generateBookCover } from '../services/geminiService';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: NewBook) => void;
  onUpdateBook: (book: Book) => void;
  bookToEdit?: Book | null;
  defaultStatus?: BookStatus;
  existingBooks: Book[];
}

interface FormErrors {
  title?: string;
  author?: string;
  pages?: string;
  rating?: string;
  currentPage?: string;
  estimatedPrice?: string;
}

export const AddBookModal: React.FC<AddBookModalProps> = ({ onClose, onAddBook, onUpdateBook, bookToEdit, defaultStatus, existingBooks }) => {
  const isEditMode = !!bookToEdit;

  const [title, setTitle] = useState(bookToEdit?.title || '');
  const [author, setAuthor] = useState(bookToEdit?.author || '');
  const [pages, setPages] = useState(bookToEdit?.pages || 0);
  const [genre, setGenre] = useState(bookToEdit?.genre || '');
  const [type, setType] = useState<BookType>(bookToEdit?.type || BookType.Book);
  const [status, setStatus] = useState<BookStatus>(bookToEdit?.status || defaultStatus || BookStatus.TBR);
  const [rating, setRating] = useState(bookToEdit?.rating?.toString() || '');
  const [yearRead, setYearRead] = useState(bookToEdit?.yearRead?.toString() || '');
  const [summary, setSummary] = useState(bookToEdit?.summary || '');
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [coverImageUrl, setCoverImageUrl] = useState<string | undefined>(bookToEdit?.coverImageUrl);
  const [isGeneratingCover, setIsGeneratingCover] = useState(false);
  const [estimatedPrice, setEstimatedPrice] = useState(bookToEdit?.estimatedPrice?.toFixed(2) || '');
  const [buyLink, setBuyLink] = useState(bookToEdit?.buyLink || '');
  const [currentPage, setCurrentPage] = useState(bookToEdit?.currentPage?.toString() || '');
  const [dateAdded, setDateAdded] = useState(bookToEdit?.dateAdded || new Date().toISOString().split('T')[0]);
  const [dateStarted, setDateStarted] = useState(bookToEdit?.dateStarted || '');
  const [dateFinished, setDateFinished] = useState(bookToEdit?.dateFinished || '');

  const [errors, setErrors] = useState<FormErrors>({});

  // Verificação de duplicata sutil
  const isDuplicate = useMemo(() => {
    if (!title.trim() || !author.trim()) return false;
    return existingBooks.some(b => 
      b.id !== bookToEdit?.id &&
      b.title.toLowerCase().trim() === title.toLowerCase().trim() &&
      b.author.toLowerCase().trim() === author.toLowerCase().trim()
    );
  }, [title, author, existingBooks, bookToEdit]);

  const validate = (): boolean => {
    const newErrors: FormErrors = {};

    if (!title.trim()) newErrors.title = "O título é obrigatório";
    if (!author.trim()) newErrors.author = "O autor é obrigatório";

    if (pages <= 0) {
        newErrors.pages = "Deve ter pelo menos 1 página";
    }

    if (status === BookStatus.Read) {
        const r = parseInt(rating, 10);
        if (isNaN(r) || r < 0 || r > 10) {
            newErrors.rating = "A nota deve ser entre 0 e 10";
        }
    }

    if (status === BookStatus.Reading || status === BookStatus.Read) {
        const curr = parseInt(currentPage, 10);
        if (status === BookStatus.Reading) {
            if (isNaN(curr) || curr < 0) newErrors.currentPage = "Página inválida";
            if (curr > pages) newErrors.currentPage = "Não pode exceder o total de páginas";
        }
    }

    if (status === BookStatus.Wishlist && estimatedPrice) {
        const price = parseFloat(estimatedPrice.replace(',', '.'));
        if (isNaN(price) || price < 0) {
            newErrors.estimatedPrice = "Preço deve ser positivo";
        }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const labelClass = "block text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1.5 ml-1";
  const getInputClass = (fieldName: keyof FormErrors) => `
    w-full bg-slate-50 border rounded-xl px-4 py-2.5 text-slate-900 outline-none transition-all
    ${errors[fieldName] 
        ? 'border-red-500 focus:ring-4 focus:ring-red-100 ring-1 ring-red-500' 
        : 'border-slate-200 focus:ring-4 focus:ring-primary/10 focus:border-primary'}
  `;

  const handlePriceBlur = () => {
    if (estimatedPrice) {
        const numeric = parseFloat(estimatedPrice.replace(',', '.'));
        if (!isNaN(numeric)) {
            setEstimatedPrice(numeric.toFixed(2));
        }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) return;

    const numericRating = rating ? parseInt(rating, 10) : undefined;
    const numericYearRead = yearRead ? parseInt(yearRead, 10) : undefined;

    let numericPrice = undefined;
    if (estimatedPrice) {
        const val = parseFloat(estimatedPrice.replace(',', '.'));
        if (!isNaN(val)) {
            numericPrice = Math.round(val * 100) / 100;
        }
    }

    const numericCurrentPage = currentPage ? parseInt(currentPage, 10) : undefined;

    const bookData = { 
        title: title.trim(), 
        author: author.trim(), 
        pages, 
        genre, 
        type, 
        status, 
        summary, 
        rating: numericRating, 
        yearRead: numericYearRead, 
        coverImageUrl, 
        estimatedPrice: numericPrice, 
        buyLink,
        currentPage: numericCurrentPage,
        dateAdded,
        dateStarted: (status === BookStatus.Reading || status === BookStatus.Read) ? (dateStarted || bookToEdit?.dateStarted) : undefined,
        dateFinished: status === BookStatus.Read ? (dateFinished || new Date().toISOString().split('T')[0]) : undefined
    };

    if (isEditMode) {
        onUpdateBook({ ...bookToEdit, ...bookData });
    } else {
        onAddBook(bookData);
    }
  };

  const handleGenerateSummary = useCallback(async () => {
    if (!title || !author) return;
    setIsGeneratingSummary(true);
    const result = await generateBookSummary(title, author);
    setSummary(result);
    setIsGeneratingSummary(false);
  }, [title, author]);

  const handleGenerateCover = useCallback(async () => {
    if (!title || !genre) return;
    setIsGeneratingCover(true);
    const result = await generateBookCover(title, genre, type);
    setCoverImageUrl(result);
    setIsGeneratingCover(false);
  }, [title, genre, type]);

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
            <h2 className="text-xl font-bold font-serif text-slate-900">{isEditMode ? 'Editar Livro' : 'Novo Livro'}</h2>
            <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 text-slate-400 transition-colors">
                <XMarkIcon className="h-5 w-5" />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6 overflow-y-auto">
            {/* Aviso de Duplicata */}
            {isDuplicate && (
              <div className="bg-amber-50 border border-amber-200 p-4 rounded-2xl flex items-center gap-3 animate-pulse">
                <div className="bg-amber-100 p-2 rounded-full">
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4 text-amber-600">
                    <path fillRule="evenodd" d="M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Zm-8-5a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 10 5Zm0 10a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z" clipRule="evenodd" />
                  </svg>
                </div>
                <p className="text-xs font-bold text-amber-700 uppercase tracking-tight">
                  Atenção: Este livro já parece existir na sua biblioteca.
                </p>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                    <label className={labelClass}>Título</label>
                    <input type="text" value={title} onChange={(e) => {setTitle(e.target.value); if(errors.title) setErrors({...errors, title: undefined});}} className={getInputClass('title')} placeholder="Ex: Dom Casmurro" />
                    {errors.title && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 uppercase tracking-tight">{errors.title}</p>}
                </div>
                <div>
                    <label className={labelClass}>Autor</label>
                    <input type="text" value={author} onChange={(e) => {setAuthor(e.target.value); if(errors.author) setErrors({...errors, author: undefined});}} className={getInputClass('author')} placeholder="Ex: Machado de Assis" />
                    {errors.author && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 uppercase tracking-tight">{errors.author}</p>}
                </div>
                <div className="grid grid-cols-2 gap-3">
                    <div>
                        <label className={labelClass}>Páginas</label>
                        <input type="number" value={pages} onChange={(e) => {setPages(Number(e.target.value)); if(errors.pages) setErrors({...errors, pages: undefined});}} className={getInputClass('pages')} />
                        {errors.pages && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 uppercase tracking-tight">{errors.pages}</p>}
                    </div>
                    <div>
                        <label className={labelClass}>Gênero</label>
                        <input type="text" value={genre} onChange={(e) => setGenre(e.target.value)} className={getInputClass('title').replace('ring-red-500', '')} placeholder="Drama" />
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <label className={labelClass}>Tipo de Mídia</label>
                    <select value={type} onChange={(e) => setType(e.target.value as BookType)} className={getInputClass('title').replace('ring-red-500', '')}>
                        <option value={BookType.Book}>Livro Físico/E-book</option>
                        <option value={BookType.HQ}>Quadrinhos / HQ</option>
                    </select>
                </div>
                <div>
                    <label className={labelClass}>Status de Leitura</label>
                    <select value={status} onChange={(e) => setStatus(e.target.value as BookStatus)} className={getInputClass('title').replace('ring-red-500', '')}>
                        <option value={BookStatus.TBR}>Quero Ler</option>
                        <option value={BookStatus.Reading}>Lendo no Momento</option>
                        <option value={BookStatus.Read}>Já Lido</option>
                        <option value={BookStatus.Wishlist}>Desejado (Wishlist)</option>
                    </select>
                </div>

                {(status === BookStatus.Reading || status === BookStatus.Read) && (
                    <div>
                        <label className={labelClass}>Início da Leitura</label>
                        <input 
                            type="date" 
                            value={dateStarted} 
                            onChange={(e) => setDateStarted(e.target.value)} 
                            className={getInputClass('title').replace('ring-red-500', '')} 
                        />
                    </div>
                )}

                {status === BookStatus.Read && (
                    <div>
                        <label className={labelClass}>Data de Conclusão</label>
                        <input 
                            type="date" 
                            value={dateFinished || new Date().toISOString().split('T')[0]} 
                            onChange={(e) => setDateFinished(e.target.value)} 
                            className={getInputClass('title').replace('ring-red-500', '')} 
                        />
                    </div>
                )}

                <div>
                    <label className={labelClass}>Data de Registro</label>
                    <input 
                      type="date" 
                      value={dateAdded} 
                      onChange={(e) => setDateAdded(e.target.value)} 
                      className={getInputClass('title').replace('ring-red-500', '')} 
                    />
                </div>

                {status === BookStatus.Reading && (
                    <div>
                        <label className={labelClass}>Página Atual</label>
                        <input type="number" value={currentPage} onChange={(e) => {setCurrentPage(e.target.value); if(errors.currentPage) setErrors({...errors, currentPage: undefined});}} className={getInputClass('currentPage')} placeholder="Ex: 45" />
                        {errors.currentPage && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 uppercase tracking-tight">{errors.currentPage}</p>}
                    </div>
                )}
            </div>

            {status === BookStatus.Read && (
                <div className="grid grid-cols-2 gap-6">
                    <div>
                        <label className={labelClass}>Nota (0-10)</label>
                        <input type="number" min="0" max="10" value={rating} onChange={(e) => {setRating(e.target.value); if(errors.rating) setErrors({...errors, rating: undefined});}} className={getInputClass('rating')} />
                        {errors.rating && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 uppercase tracking-tight">{errors.rating}</p>}
                    </div>
                    <div>
                        <label className={labelClass}>Ano que Leu</label>
                        <input type="number" value={yearRead} onChange={(e) => setYearRead(e.target.value)} className={getInputClass('title').replace('ring-red-500', '')} placeholder={new Date().getFullYear().toString()} />
                    </div>
                </div>
            )}

            {status === BookStatus.Wishlist && (
              <div className="p-6 bg-slate-50 rounded-2xl border border-slate-200 grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="md:col-span-2">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Informações de Compra</h4>
                  </div>
                  <div className="md:col-span-1">
                      <label className={labelClass}>Valor Estimado</label>
                      <div className="relative group/price">
                          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold text-sm pointer-events-none group-focus-within/price:text-primary">R$</span>
                          <input 
                            type="text"
                            inputMode="decimal"
                            value={estimatedPrice} 
                            onChange={(e) => {
                                const val = e.target.value.replace(',', '.');
                                if (val === '' || /^\d*\.?\d*$/.test(val)) {
                                    setEstimatedPrice(e.target.value);
                                    if(errors.estimatedPrice) setErrors({...errors, estimatedPrice: undefined});
                                }
                            }} 
                            onBlur={handlePriceBlur}
                            className={`${getInputClass('estimatedPrice')} pl-11`} 
                            placeholder="0,00"
                          />
                      </div>
                      {errors.estimatedPrice && <p className="text-[10px] text-red-500 font-bold mt-1 ml-1 uppercase tracking-tight">{errors.estimatedPrice}</p>}
                  </div>
                  <div className="md:col-span-2">
                      <label className={labelClass}>Link para Loja</label>
                      <input 
                        type="url" 
                        value={buyLink} 
                        onChange={(e) => setBuyLink(e.target.value)} 
                        className={getInputClass('title').replace('ring-red-500', '')} 
                        placeholder="https://amazon.com.br/exemplo"
                      />
                  </div>
              </div>
            )}

            <div className="p-6 bg-blue-50/50 rounded-2xl border border-blue-100 flex flex-col sm:flex-row items-center gap-6">
                <div className="relative group">
                    {coverImageUrl ? (
                        <img src={coverImageUrl} alt="Capa" className="w-24 h-36 object-cover rounded-xl shadow-xl transition-all group-hover:scale-105"/>
                    ) : (
                        <div className="w-24 h-36 bg-slate-200 rounded-xl flex items-center justify-center">
                            <BookOpenIcon className="h-8 w-8 text-slate-400" />
                        </div>
                    )}
                </div>
                <div className="flex-1 text-center sm:text-left">
                    <h4 className="text-sm font-bold text-slate-800 mb-1">Capa Personalizada</h4>
                    <p className="text-xs text-slate-500 mb-4">Gere uma arte exclusiva via IA baseada nos dados do livro.</p>
                    <button type="button" onClick={handleGenerateCover} disabled={isGeneratingCover} className="px-4 py-2 text-xs font-bold rounded-lg bg-white text-primary border border-blue-200 hover:bg-blue-600 hover:text-white transition-all shadow-sm active:scale-95 disabled:opacity-50">
                        {isGeneratingCover ? 'Criando arte...' : 'Gerar com IA'}
                    </button>
                </div>
            </div>

            <div>
                <label className={labelClass}>Resumo & Reflexões</label>
                <textarea value={summary} onChange={(e) => setSummary(e.target.value)} rows={3} className={getInputClass('title').replace('ring-red-500', '')} placeholder="Sobre o que é este livro?"></textarea>
                <button type="button" onClick={handleGenerateSummary} disabled={isGeneratingSummary} className="mt-2 text-[10px] font-bold text-primary uppercase tracking-widest hover:underline disabled:opacity-50">
                    {isGeneratingSummary ? 'Redigindo...' : '✦ Gerar resumo inteligente'}
                </button>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-slate-100">
                <button type="button" onClick={onClose} className="px-6 py-2.5 rounded-xl text-slate-500 font-bold hover:bg-slate-100 transition-all">Descartar</button>
                <button type="submit" className="px-8 py-2.5 rounded-xl bg-primary text-white font-bold hover:bg-blue-700 shadow-lg shadow-primary/20 transition-all active:scale-95">
                    {isEditMode ? 'Salvar Edição' : 'Adicionar à Estante'}
                </button>
            </div>
        </form>
      </div>
    </div>
  );
};

import React from 'react';
import type { Book } from '../types';
import { BookStatus } from '../types';
import { StarIcon } from './Icons';

interface BookListItemProps {
  book: Book;
  onEdit: (book: Book) => void;
  onDelete: (book: Book) => void;
}

const StarRating: React.FC<{ rating: number }> = ({ rating }) => {
  return (
    <div className="flex items-center gap-0.5">
      {[...Array(10)].map((_, index) => (
        <StarIcon
          key={index}
          className={`h-3.5 w-3.5 ${index < rating ? 'text-amber-400 fill-current' : 'text-slate-200'}`}
        />
      ))}
    </div>
  );
};

const getStatusBadgeStyles = (status: BookStatus) => {
    switch(status) {
        case BookStatus.Read: return 'bg-emerald-50 text-emerald-600 border-emerald-100/50';
        case BookStatus.Reading: return 'bg-blue-50 text-blue-600 border-blue-100/50';
        case BookStatus.TBR: return 'bg-slate-50 text-slate-500 border-slate-100/50';
        case BookStatus.Wishlist: return 'bg-pink-50 text-pink-600 border-pink-100/50';
        default: return 'bg-slate-50 text-slate-500 border-slate-100/50';
    }
}

const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    const [year, month, day] = dateStr.split('-');
    return `${day}/${month}/${year}`;
}

const calculateDaysReading = (startDate?: string) => {
    if (!startDate) return 0;
    const start = new Date(startDate);
    const today = new Date();
    today.setHours(0,0,0,0);
    start.setHours(0,0,0,0);
    const diffTime = Math.abs(today.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
}

const calculateReadingDuration = (start?: string, end?: string) => {
    if (!start || !end) return null;
    const startDate = new Date(start);
    const endDate = new Date(end);
    startDate.setHours(0,0,0,0);
    endDate.setHours(0,0,0,0);
    const diffTime = endDate.getTime() - startDate.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
    return diffDays > 0 ? diffDays : 1;
}

export const BookListItem: React.FC<BookListItemProps> = ({ book, onEdit, onDelete }) => {
  const isRead = book.status === BookStatus.Read;
  const daysReading = book.status === BookStatus.Reading ? calculateDaysReading(book.dateStarted) : 0;
  const readingDuration = isRead ? calculateReadingDuration(book.dateStarted, book.dateFinished) : null;

  return (
    <article className="bg-white p-6 md:p-7 rounded-[2.5rem] shadow-soft border border-slate-100 flex flex-col md:flex-row items-center gap-8 transition-all duration-500 hover:shadow-[0_20px_40px_-12px_rgba(0,0,0,0.06)] hover:-translate-y-1.5 hover:border-primary/10 group">

      {/* Cover Container with Realistic 3D Hover */}
      <div className="relative flex-shrink-0 perspective-1000">
        <div className="relative group/cover transition-transform duration-700 ease-out group-hover:rotate-y-12">
          <img
            src={book.coverImageUrl || `https://picsum.photos/seed/${encodeURIComponent(book.title)}/400/600`}
            alt={`Capa do livro ${book.title}`}
            className="w-28 h-40 md:w-32 md:h-48 object-cover rounded-2xl shadow-[0_10px_30px_rgba(0,0,0,0.12)] transition-all duration-700 group-hover:shadow-[0_25px_50px_rgba(0,0,0,0.2)]"
          />
          {/* Sombra de lombada de livro */}
          <div className="absolute inset-y-0 left-0 w-1.5 bg-gradient-to-r from-black/20 to-transparent rounded-l-2xl"></div>
          {/* Overlay de brilho sutil */}
          <div className="absolute inset-0 rounded-2xl shadow-[inset_0_0_30px_rgba(255,255,255,0.1)] pointer-events-none border border-white/10"></div>
        </div>
      </div>

      <div className="flex-1 text-center md:text-left min-w-0">
        <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4 mb-2">
            <div className="min-w-0">
                <h3 className="text-2xl font-black text-slate-900 leading-tight font-serif italic truncate group-hover:text-primary transition-colors duration-300">
                  {book.title}
                </h3>
                <p className="text-lg text-slate-400 font-semibold">{book.author}</p>
            </div>

            <div className="flex flex-wrap items-center gap-2 justify-center md:justify-start xl:justify-end">
                {daysReading > 0 && (
                    <span className="flex items-center gap-1 text-[10px] font-black text-blue-600 bg-blue-50/50 px-3 py-1.5 rounded-xl border border-blue-100/50 uppercase tracking-widest">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3">
                            <path fillRule="evenodd" d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm.75-13a.75.75 0 0 0-1.5 0v5c0 .414.336.75.75.75h4a.75.75 0 0 0 0-1.5h-3.25V5Z" clipRule="evenodd" />
                        </svg>
                        Há {daysReading} {daysReading === 1 ? 'dia' : 'dias'}
                    </span>
                )}
                {readingDuration !== null && (
                    <span className="flex items-center gap-1 text-[10px] font-black text-emerald-600 bg-emerald-50/50 px-3 py-1.5 rounded-xl border border-emerald-100/50 uppercase tracking-widest">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3">
                            <path fillRule="evenodd" d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm3.857-9.809a.75.75 0 0 0-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 1 0-1.06 1.061l2.5 2.5a.75.75 0 0 0 1.137-.089l4-5.5Z" clipRule="evenodd" />
                        </svg>
                        Lido em {readingDuration} {readingDuration === 1 ? 'dia' : 'dias'}
                    </span>
                )}
                <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest whitespace-nowrap">
                   Registrado em {formatDate(book.dateAdded)}
                </span>
            </div>
        </div>

        <div className="flex flex-wrap justify-center md:justify-start items-center gap-3 mb-6 mt-4">
            <span className={`px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] border shadow-sm ${getStatusBadgeStyles(book.status)}`}>
                {book.status}
            </span>
            <span className="px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] border bg-slate-50 text-slate-500 border-slate-100 shadow-sm">
                {book.type}
            </span>
            <span className="px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.1em] border bg-slate-50 text-slate-500 border-slate-100 shadow-sm">
                {book.pages} páginas
            </span>
        </div>

        {book.rating && book.status === BookStatus.Read && (
            <div className="flex justify-center md:justify-start items-center gap-4 mb-4 bg-slate-50/50 p-2 rounded-2xl w-fit">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Avaliação</span>
                <StarRating rating={book.rating} />
            </div>
        )}

        {book.summary && (
            <div className="relative mt-4">
                <p className="text-sm text-slate-400 italic leading-relaxed line-clamp-2 group-hover:line-clamp-none transition-all duration-500 ease-in-out">
                    "{book.summary}"
                </p>
            </div>
        )}
      </div>

      {/* Modernized Action Buttons */}
      <div className="flex flex-row md:flex-col gap-3 w-full md:w-44 mt-4 md:mt-0">
        <button
          onClick={() => onEdit(book)}
          className="flex-1 px-6 py-3 text-[11px] font-black rounded-2xl bg-slate-900 text-white hover:bg-primary shadow-lg shadow-slate-900/10 hover:shadow-primary/20 transition-all active:scale-95 uppercase tracking-widest"
        >
          Editar
        </button>
        <button
          onClick={() => onDelete(book)}
          className="flex-1 px-6 py-3 text-[11px] font-black rounded-2xl bg-white text-red-400 hover:bg-red-50 hover:text-red-600 border border-red-100 transition-all active:scale-95 uppercase tracking-widest"
        >
